namespace ghidra.feature.vt.gui.util;






using docking.util;
using generic.theme;
using ghidra.feature.vt.gui.filters;

public class FilterIconFlashTimer<T> : Timer, ActionListener {

	private static readonly Icon EMPTY_ICON = new GIcon("icon.version.tracking.empty");
	private static readonly long MINIMUM_TIME_BETWEEN_FLASHES = 20000;
	private static readonly int MAX_FLASH_COUNT = 10;

	private int flashCount = 0;
	private long lastFlashTime;

	private JButton filterButton;
	private AncillaryFilterDialogComponentProvider<T> filterDialog;
	private Icon baseIcon;
	private Icon filteredIcon;

	public FilterIconFlashTimer(Icon baseIcon, Icon filteredIcon,
			AncillaryFilterDialogComponentProvider<T> filterDialog, JButton filterButton) : base(250, null)
    {
		this.baseIcon = baseIcon;
		this.filteredIcon = filteredIcon;
		this.filterDialog = filterDialog;
		this.filterButton = filterButton;
		addActionListener(this);
	}

	/* @Override */
	public void actionPerformed(ActionEvent @event) {
		if (!AnimationUtils.isAnimationEnabled()) {
			stop();
			return;
		}

		if (!filterDialog.isFiltered()) {
			stop();
			return; // no filter applied
		}

		if (flashCount < MAX_FLASH_COUNT) {
			changeIcon();
			flashCount++;
		}
		else {
			stop();
			stallAnimation();
		}
	}

	/* @Override */
	public void restart() {
		if ((DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - lastFlashTime) < MINIMUM_TIME_BETWEEN_FLASHES) {
			return;
		}

		flashCount = 0;
		base.restart();
	}

	/* @Override */
	public void stop() {
		base.stop();
		restoreBaseIcon();
		flashCount = 0;
	}

	private void changeIcon() {
		Icon currentIcon = filterButton.getIcon();
		if (currentIcon == filteredIcon) {
			filterButton.setIcon(EMPTY_ICON);
		}
		else {
			filterButton.setIcon(filteredIcon);
		}
	}

	private void restoreBaseIcon() {
		if (filterDialog.isFiltered()) {
			filterButton.setIcon(filteredIcon);
		}
		else {
			filterButton.setIcon(baseIcon);
		}
	}

	private void stallAnimation() {
		// this prevents focus from flashing for MINIMUM_TIME_BETWEEN_FLASHES
		lastFlashTime = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
	}
}
